sql.if:
AND EXISTS (
  SELECT 1 FROM save_tags st JOIN tags t ON t.id = st.tag_id
  WHERE st.save_id = s.id AND lower(t.name) IN
  #{tag}
)



AND (
  s.search_vector @@ to_tsquery('simple', ari_unaccent(#{prefixQuery}))
  OR ari_unaccent(lower(s.text)) LIKE ari_unaccent(#{containsPattern}) ESCAPE '\'

    OR s.source_id IN
    #{sourceId}

)

mapper.select:
SELECT  FROM saves s
WHERE s.user_id = #{userId} AND s.id IN
#{id}

SELECT FROM saves s WHERE s.user_id = #{userId}
AND (COALESCE(s.page_number, 0), s.created_at, s.id) > (#{after.pageNumber}, #{after.createdAt}, #{after.id})
ORDER BY COALESCE(s.page_number, 0), s.created_at, s.id
AND (s.created_at, s.id) < (#{after.createdAt}, #{after.id}) ORDER BY s.created_at DESC, s.id DESC
LIMIT #{limit}

SELECT s.kind AS kind, count(*) AS count FROM saves s
WHERE s.user_id = #{userId}

GROUP BY s.kind
